# Code generated by Claude
"""
Tests of the controller modes (auto / teleop) with the beaker-on-hotplate task policy, headless, with scripted keys.

    MUJOCO_GL=egl python experiments/cc_mode_tests.py [A B C1 C2]

A   auto / hold stage. At handoff + 100 ticks F9 (operator takes over), the operator drives the base back a little (arrow key, then SPACE),
    at handoff + 200 F9 again (control returns to auto, the policy continues its stage). With timeout_after_handoff = 5 s:
    the switches are logged with cause operator_key, the base moved under the operator, the auto clock was paused while the operator had
    control (auto time 5.008 s = 313 ticks, operator time 1.6 s = 100 ticks) and the episode ends as an AUTO timeout.
B   auto / request_operator stage + a test source that teleports the beaker onto the hotplate at 46 s (after the request, so under teleop):
    the policy's request switches to teleop at the handoff (cause policy_request), the auto clock stays at 0, and the episode is
    SUCCESS with operator_assisted true.
C1  teleop start (no policy), the beaker teleported at ~3 s: time 0 is the handoff, success is checked from the start: SUCCESS, operator_assisted.
C2  teleop start, nothing happens, operator_timeout = 5 s: TIMEOUT of kind operator after 5.0 s.
"""

import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import glfw  # noqa: E402
import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.episode_test_sources import make_cheat_arm_stage  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import EPISODE_CFG  # noqa: E402
from src.task_policy import make_request_operator_stage  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(ok)
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def make_probe():
    probe = {"H": None, "poses": {}}

    def step(obs):
        if probe["H"] is None and obs.get("policy") and obs["policy"]["handoff"]:
            probe["H"] = obs["tick"]
        probe["poses"][obs["tick"]] = obs["base_pose"]
        return None

    return {"name": "probe", "step": step, "state": probe}, probe


def scenario_A(model, data):
    print("\nA: auto / hold, F9 takeover at handoff+100 and resume at handoff+200 (auto timeout 5 s)")
    tick = [0]
    src, probe = make_probe()

    def held(code):
        H = probe["H"]
        if H is None:
            return False
        k = tick[0] - H
        if code == glfw.KEY_F9:
            return k in (100, 101, 200, 201)
        if code == glfw.KEY_DOWN:
            return 110 <= k <= 124
        if code == glfw.KEY_SPACE:
            return 125 <= k <= 145
        return False

    s = run_episode(None, model, data, episode_cfg={**EPISODE_CFG, "timeout_after_handoff": 5.0}, held=held, loop_cfg={"tick_ref": tick},
                    extra_sources=lambda m, d: {"probe": src})
    sw = s["mode_switches"]
    check("switch log: initial auto, operator_key to teleop, operator_key back", [(m["from"], m["to"], m["cause"]) for m in sw] ==
          [("teleop", "auto", "initial"), ("auto", "teleop", "operator_key"), ("teleop", "auto", "operator_key")], str([m["cause"] for m in sw]))
    H = probe["H"]
    moved = np.hypot(*(np.array(probe["poses"][H + 150][:2]) - np.array(probe["poses"][H + 105][:2])))
    check("the base moved under the operator", moved > 0.03, f"{1000 * moved:.0f} mm between handoff+105 and +150")
    still = np.hypot(*(np.array(probe["poses"][H + 100][:2]) - np.array(probe["poses"][H + 5][:2])))
    check("the base did not move under auto (hold stage)", still < 0.002, f"{1000 * still:.1f} mm")
    check("auto clock paused during operator control", abs(s["auto_time_after_handoff_s"] - 5.0) < 0.02 and abs(s["operator_time_s"] - 1.6) < 0.05,
          f"auto {s['auto_time_after_handoff_s']:.3f} s, operator {s['operator_time_s']:.3f} s")
    check("outcome TIMEOUT (auto)", s["outcome"] == "TIMEOUT" and s["timeout_kind"] == "auto", f"{s['outcome']} {s['timeout_kind']}")


def scenario_B(model, data):
    print("\nB: auto / request_operator, beaker teleported at ~46 s (under teleop)")
    s = run_episode(lambda m, d: make_request_operator_stage(), model, data,
                    extra_sources=lambda m, d: {"cheat": make_cheat_arm_stage(m, d, delay_s=44.6)})
    sw = s["mode_switches"]
    check("policy_request switch at the handoff, stage request_operator", len(sw) == 2 and sw[1]["cause"] == "policy_request" and sw[1]["to"] == "teleop"
          and sw[1]["stage"] == "request_operator" and abs(sw[1]["time"] - s["handoff_time"]) < 0.05, str(sw[-1]))
    check("auto clock stayed at ~0 (the request came on the first tick after handoff)", s["auto_time_after_handoff_s"] < 0.05, f"{s['auto_time_after_handoff_s']:.3f} s")
    check("SUCCESS with operator_assisted", s["outcome"] == "SUCCESS" and s["operator_assisted"], f"{s['outcome']} operator_time {s['operator_time_s']:.1f} s")


def scenario_C(model, data):
    print("\nC1: teleop start, beaker teleported at ~3 s")
    s = run_episode(None, model, data, mode="teleop", extra_sources=lambda m, d: {"cheat": make_cheat_arm_stage(m, d, delay_s=1.6)})
    check("handoff at the start, SUCCESS, operator_assisted", s["handoff_time"] is not None and s["handoff_time"] < 1.5 + 0.05 and s["outcome"] == "SUCCESS"
          and s["operator_assisted"] and not s["mode_switches"], f"{s['outcome']} at {s['sim_time_end']:.2f} s, handoff {s['handoff_time']:.2f} s")
    print("\nC2: teleop start, nothing happens, operator_timeout 5 s")
    s = run_episode(None, model, data, mode="teleop", episode_cfg={**EPISODE_CFG, "operator_timeout": 5.0})
    check("TIMEOUT of kind operator after 5.0 s", s["outcome"] == "TIMEOUT" and s["timeout_kind"] == "operator" and abs(s["operator_time_s"] - 5.0) < 0.02,
          f"{s['outcome']} {s['timeout_kind']} operator {s['operator_time_s']:.3f} s")


def main():
    which = sys.argv[1:] or ["A", "B", "C1", "C2"]
    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    if "A" in which:
        scenario_A(model, data)
    if "B" in which:
        scenario_B(model, data)
    if "C1" in which or "C2" in which:
        scenario_C(model, data)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)


if __name__ == "__main__":
    main()
